"""Write rulefetch/html5_entities.go: CPython 3.11's html.entities.html5 and
html._invalid_charrefs / _invalid_codepoints, the tables of html.unescape.

Run: PYTHONPATH=. ~/cf-test/.venv/bin/python server/internal/rulefetch/testdata/gen_html5.py
"""
import html
import html.entities
import os
import sys

out = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'html5_entities.go')


def go(s):
    out = []
    for c in s:
        o = ord(c)
        if c in '"\\':
            out.append('\\' + c)
        elif 0x20 <= o < 0x7f:
            out.append(c)
        elif o <= 0xffff:
            out.append('\\u%04x' % o)
        else:
            out.append('\\U%08x' % o)
    return '"' + ''.join(out) + '"'


lines = ['// Code generated by testdata/gen_html5.py from CPython %s; DO NOT EDIT.' % sys.version.split()[0], '',
         'package rulefetch', '',
         '// html5Entities is html.entities.html5 (names with and without ";").',
         'var html5Entities = map[string]string{']
for name in sorted(html.entities.html5):
    lines.append('\t%s: %s,' % (go(name), go(html.entities.html5[name])))
lines += ['}', '', '// invalidCharrefs is html._invalid_charrefs.', 'var invalidCharrefs = map[int]string{']
for num in sorted(html._invalid_charrefs):
    lines.append('\t0x%x: %s,' % (num, go(html._invalid_charrefs[num])))
lines += ['}', '', '// invalidCodepoints is html._invalid_codepoints.', 'var invalidCodepoints = map[int]bool{']
for num in sorted(html._invalid_codepoints):
    lines.append('\t0x%x: true,' % num)
lines += ['}', '']
with open(out, 'w') as fh:
    fh.write('\n'.join(lines))
print(len(html.entities.html5), 'entities')
